/* aesthetic shellapp v2.24.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-w-medium: 550;
  --ae-space-4: 1em;
  --ae-space-5: 1.5em;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-h {
font-weight: var(--ae-w-medium);
  color: var(--ae-ink-muted);
  letter-spacing: 0.18em;
  margin-bottom: 0.7em;
}

.ae-shell {
height: 100dvh;
  display: grid;
  grid-template-columns: 14rem minmax(0, 1fr);
  overflow: hidden;
}

.ae-rail {
border-right: 1px solid var(--ae-line);
  padding: 1.6em 1.4em;
  font-size: 13px;
  color: var(--ae-ink-muted);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.ae-rail .ae-h {
margin-top: 1.8em;
}

.ae-rail .ae-h:first-child {
margin-top: 0;
}

.ae-rail a {
display: block;
  width: 100%;
  background: transparent;
  border: 0;
  font: inherit;
  line-height: inherit;
  text-align: left;
  text-decoration: none;
  color: var(--ae-ink-muted);
  padding: 0.3em 0;
  margin-block: 0;
  cursor: pointer;
  transition: color var(--ae-quick) var(--ae-ease);
}

.ae-rail a:hover,
.ae-rail button:hover {
color: var(--ae-ink);
}

.ae-rail [aria-current],
.ae-rail .is-active {
color: var(--ae-ink);
  font-weight: var(--ae-w-medium);
}

.ae-rail-foot {
margin-top: auto;
  padding-top: 1.6em;
}

.ae-desk {
min-width: 0;
  overflow-y: auto;
  padding: 2.2em 2.8em;
}

@media (max-width: 48rem) {
  .ae-shell {
  grid-template-columns: 1fr;
      grid-template-rows: minmax(0, 1fr) auto;
  }

  .ae-rail {
  grid-column: 1;
      grid-row: 2;
      min-width: 0;
      border-right: 0;
      border-top: 1px solid var(--ae-line);
      padding: 0 1.2rem;
      overflow: auto hidden;
      flex-direction: row;
      align-items: center;
      gap: var(--ae-space-5);
  }

  .ae-rail .ae-h {
  display: none;
  }

  .ae-rail a {
  flex: none;
      width: auto;
      padding: 0.85em 0;
      white-space: nowrap;
  }

  .ae-rail-foot {
  flex: none;
      margin-top: 0;
      margin-left: auto;
      padding-top: 0;
  }

  .ae-desk {
  grid-column: 1;
      grid-row: 1;
      min-height: 0;
      padding: 1.8em 1.6rem;
  }
}

@media (max-width: 40rem) {
  .ae-shell {
  grid-template-columns: 1fr;
  }

  .ae-rail {
  padding-inline: 1.2rem;
      gap: var(--ae-space-4);
  }

  .ae-desk {
  padding: 1.6em 1.2rem;
  }
}
